24	int printUsage() {
25	    std::cerr << "Usage: sealmark --version\n"
26	                 "       sealmark digest <file>\n"
27	                 "       sealmark verify-digest <file> <expected-digest>\n"
28	                 "       sealmark key-id <public-key-file>\n";
29	    return 2;
30	}
